INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('2cb040b743c2c1de', 'brand_bonk_golf', '8eecd03d45cecb57', 1, 1, 1, 'live', 'How long until he notices', 'A gift prank: he thinks it is a normal hat until he finds the magnet marker.', 'Wives and girlfriends', 'Any hat', 'Gift reaction', '["I got my husband a golf hat. Let us see how long it takes him to notice.", "He has no idea what this hat does yet.", "Watch his face."]', '[{"label": "Open · 0 to 3s", "text": "Whisper the plan, hat in hand."}, {"label": "Middle", "text": "Hand it over: \"nice, a hat.\" Then he finds the marker."}, {"label": "Close", "text": "\"Took you long enough.\""}]', 'You whisper to the camera while he is in the next room.', '"Wait, what is this?" when he finds the marker.', '[{"brand": "Bogey Bros", "what": "\"I got my husband a hat. Let us see how long it takes him to notice the marker.\" Film his reaction.", "url": null}]');
