INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('67f0e1f9395e3814', 'brand_bonk_golf', '9676c217d88066ba', 1, 3, 3, 'live', 'One hat, my whole day', 'One hat that does the whole day, so you stop owning a hat for everything.', 'Golfers with a job, a family and a tee time', 'Any snapback', 'Day in the life, talk over it', '["I used to own a hat for everything.", "One hat. My whole day.", "Work, golf, dinner. Same hat."]', '[{"label": "Open · 0 to 3s", "text": "Hat on the dash or desk, grab it."}, {"label": "Middle", "text": "Work, then the course: marker off the bill on the green."}, {"label": "Close", "text": "Dinner or the bar, hat still on. \"Just this one.\""}]', 'The hat sitting on your dashboard or desk, then you grab it.', 'Hard cut from work clothes to the first tee, same hat.', '[{"brand": "Melin", "what": "\"I used to pack five hats.\" Film your day: work, the course, dinner. Same Bonk hat in every shot.", "url": null}]');
